      return (
        <section className={className}>
          <h1>{title}</h1>
          {children}
        </section>
      )
    }

    function Button({ children }) {
      const theme = useContext(ThemeContext);
      const className = 'button-' + theme;
      return (
        <button className={className}>
          {children}
        </button>
      );
    }

    .panel-light,
    .panel-dark {
      border: 1px solid black;
      border-radius: 4px;
      padding: 20px;
      margin-bottom: 10px;
    }
