Note that value="dark" passes the "dark" string, but value={theme} passes the value of the JavaScript theme variable with JSX curly braces. Curly braces also let you pass context values that aren't strings.

Updating an object via context

In this example, there is a currentUser state variable which holds an object. You combine { currentUser, setCurrentUser } into a single object and pass it down through the context inside the value={}. This lets any component below, such as LoginButton, read both currentUser and setCurrentUser, and then call setCurrentUser when needed.

    import { createContext, useContext, useState } from 'react';

    const CurrentUserContext = createContext(null);

    export default function MyApp() {
      const [currentUser, setCurrentUser] = useState(null);
      return (
        <CurrentUserContext
          value={{
            currentUser,
            setCurrentUser
          }}
        >
          <Form />
        </CurrentUserContext>
      );
    }

    function Form({ children }) {
      return (
        <Panel title="Welcome">
          <LoginButton />
        </Panel>
      );
    }

    function LoginButton() {
      const {
        currentUser,
        setCurrentUser
      } = useContext(CurrentUserContext);

      if (currentUser !== null) {
        return <p>You logged in as {currentUser.name}.</p>;
      }

      return (
        <Button onClick={() => {
          setCurrentUser({ name: 'Advika' })
        }}>Log in as Advika</Button>
      );
    }

    function Panel({ title, children }) {
      return (
        <section className="panel">
          <h1>{title}</h1>
          {children}
        </section>
      )
    }

    function Button({ children, onClick }) {
      return (
        <button className="button" onClick={onClick}>
          {children}
        </button>
      );
    }

    label {
      display: block;
    }

    .panel {
      border: 1px solid black;
      border-radius: 4px;
      padding: 20px;
      margin-bottom: 10px;
    }

    .button {
      border: 1px solid #777;
      padding: 5px;
      margin-right: 10px;
      margin-top: 10px;
    }

