    }

    const intl = new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD"
    });

    export default function Total({ clientQuantity, savedQuantity, isPending }) {
      return (
        <div className="total">
          <span>Total:</span>
          <div>
            <div>
              {isPending
                ? "🌀 Updating..."
